import re
p = 'gson/src/main/java/com/google/gson/internal/bind/TypeAdapters.java'
s = open(p).read()
for prim, call in [('byteValue','byteValue'), ('shortValue','shortValue'), ('intValue','intValue'), ('longValue','longValue'), ('floatValue','floatValue'), ('doubleValue','doubleValue')]:
    old = """    public void write(JsonWriter out, Number value) throws IOException {
      out.value(value.%s());
    }""" % call
    new = """    public void write(JsonWriter out, Number value) throws IOException {
      if (value == null) {
        out.nullValue();
        return;
      }
      out.value(value.%s());
    }""" % call
    assert s.count(old) == 1, (call, s.count(old))
    s = s.replace(old, new)
open(p, 'w').write(s)
print("done")
EOF

